/** @param {Record<string, unknown>} tile @param {'bundled'|'public'|'user'} trust */
function withExtensionTrust(tile, trust) {
    return { ...tile, extensionTrust: trust };
}

export function collectExtensionHomeTiles(sources = {}) {
    const out = [];
    const bundled = parseShellExtensionRegistry(sources.bundled);
    bundled.extensions.forEach((e) => e.tiles.forEach((t) => out.push(withExtensionTrust(t, 'bundled'))));
    if (sources.remote) {
        const remote = parseShellExtensionRegistry(sources.remote);
        remote.extensions.forEach((e) => e.tiles.forEach((t) => out.push(withExtensionTrust(t, 'public'))));
    }
    const user = sources.user || loadUserShellExtensionRegistry();
    user.extensions.forEach((e) => e.tiles.forEach((t) => out.push(withExtensionTrust(t, 'user'))));
    return out;
}

/** @typedef {{ id: string, label: string, subtitle?: string, icon?: string, action: Record<string, unknown> }} HomeTile */
/** @typedef {'bundled' | 'public' | 'user'} ExtensionTrust */

/** @param {ExtensionTrust | undefined} trust */
function extensionTrustBadge(trust) {
    if (trust === 'bundled') {
        return { short: 'Shipped', className: 'text-emerald-300/90', title: 'Bundled with NeuralShell' };
    }
    if (trust === 'public') {
        return { short: 'Public', className: 'text-sky-300/90', title: 'From the online shell-extensions registry' };
    }
    if (trust === 'user') {
        return { short: 'Imported', className: 'text-amber-300/90', title: 'Imported from a JSON pack on this device' };
    }
    return { short: 'ext', className: 'text-violet-300/90', title: '' };
}

