async function openMoreTab(tabId, label, failures) {
    // Prefer test ids when available; fall back to visible label for stale dist bundles.
    const clickedById = await clickIfVisible(tabId, failures);
    if (clickedById) return true;
    const labelMatch = page.locator('button:visible').filter({ hasText: new RegExp(`^${label}$`) }).last();
    if (!(await labelMatch.count())) {
        failures.push(`open ${label.toLowerCase()} tab: no visible "${label}" tab control`);
        return false;
    }

    try {
        await labelMatch.click({ timeout: 6000, force: true });
        await page.waitForTimeout(120);
        return true;
    } catch (err) {
        failures.push(`open ${label.toLowerCase()} tab: ${err && err.message ? err.message : String(err)}`);
        return false;
    }
}

