async function ensureMoreMenuOpen(failures) {
    const startedAt = Date.now();
    const panelsTab = page.getByTestId('more-tab-panels-btn').first();
    if (await panelsTab.isVisible().catch(() => false)) return true;

    for (let attempt = 0; attempt < 3; attempt += 1) {
        const opened = await clickIfVisible('more-menu-btn', failures);
        if (!opened) {
            const raw = page.getByTestId('more-menu-btn').first();
            if (await raw.count()) {
                await raw.scrollIntoViewIfNeeded().catch(() => {});
                await raw.click({ timeout: DEFAULT_CLICK_TIMEOUT_MS }).catch(() => {});
                await page.waitForTimeout(180);
            }
        }
        if (await panelsTab.isVisible().catch(() => false)) {
            if (runtimeMetrics.firstMoreMenuOpenMs == null) {
                runtimeMetrics.firstMoreMenuOpenMs = Date.now() - startedAt;
            }
            return true;
        }
        await page.waitForTimeout(200);
    }
    return false;
}

async function openMoreTab(tabId, label, failures) {
    // Do not route through clickIfVisible — it runs dismissBlockingOverlays; tab switches must stay in-menu.
    const tab = page.getByTestId(tabId).first();
    const clickTab = async () => {
        await tab.waitFor({ state: 'visible', timeout: DEFAULT_CLICK_TIMEOUT_MS });
        await tab.scrollIntoViewIfNeeded();
        await tab.click({ timeout: DEFAULT_CLICK_TIMEOUT_MS });
        await page.waitForTimeout(100);
    };
    try {
        if (!(await tab.count())) {
            throw new Error(`missing ${tabId}`);
        }
        await clickTab();
        return true;
    } catch (firstErr) {
        await ensureMoreMenuOpen(failures);
        try {
            if (!(await tab.count())) {
                throw firstErr;
            }
            await clickTab();
            return true;
        } catch (secondErr) {
            failures.push(`open ${label.toLowerCase()} tab (${tabId}): ${secondErr && secondErr.message ? secondErr.message : String(secondErr)}`);
        }
    }
    const labelMatch = page
        .locator('button:visible')
        .filter({ hasText: new RegExp(`^\\s*${label}\\s*$`, 'i') })
        .first();
    if (!(await labelMatch.count())) {
        failures.push(`open ${label.toLowerCase()} tab: no visible "${label}" tab control`);
        return false;
    }
    try {
        await labelMatch.scrollIntoViewIfNeeded();
        await labelMatch.click({ timeout: DEFAULT_CLICK_TIMEOUT_MS, force: true });
        await page.waitForTimeout(120);
        return true;
    } catch (err) {
        failures.push(`open ${label.toLowerCase()} tab (label fallback): ${err && err.message ? err.message : String(err)}`);
        return false;
    }
}

