/**
 * Mirrors panel/extension id guards in src/renderer/src/lib/shellExtensions.js
 * so regressions are caught without bundling the ESM renderer module in Node.
 */
const assert = require("assert");

const SAFE_PANEL = /^[a-z0-9][a-z0-9_-]{0,62}$/i;
const SAFE_EXT_ID = /^[a-z0-9][a-z0-9._-]{0,120}$/i;
const SAFE_HASH = /^#(\/[a-zA-Z0-9/_-]{0,120}|[a-zA-Z0-9_-]{1,80})$/;

function assertPanelRejected(slug) {
  assert.strictEqual(
    SAFE_PANEL.test(slug),
    false,
    `panel slug must be rejected: ${JSON.stringify(slug)}`,
  );
}

function assertPanelAccepted(slug) {
  assert.strictEqual(SAFE_PANEL.test(slug), true, `panel slug must be accepted: ${JSON.stringify(slug)}`);
}

function assertExtIdAccepted(id) {
  assert.strictEqual(SAFE_EXT_ID.test(id), true, `extension id must be accepted: ${JSON.stringify(id)}`);
}

console.log("[shell-extension-action-safety] validating panel slug allowlist…");
assertPanelAccepted("command-center");
assertPanelAccepted("runtime-events");
assertPanelRejected("../../../etc/passwd");
assertPanelRejected("..");
assertPanelRejected("");

console.log("[shell-extension-action-safety] validating extension id allowlist…");
assertExtIdAccepted("neuralshell.bundled.starter");
assertExtIdAccepted("e2eTrustUserPack");
assertExtIdAccepted("community.quickops.pack1");

console.log("[shell-extension-action-safety] validating hash pattern (no traversal)…");
assert.strictEqual(SAFE_HASH.test("#/scratchpad"), true);
assert.strictEqual(SAFE_HASH.test("#/operator-home"), true);
assert.strictEqual(SAFE_HASH.test("#/../etc"), false);

console.log("[shell-extension-action-safety] PASS");

