/**
 * Study coach — single source for /learn, /homework, subject pills, and pane starters.
 * Prompts emphasize tutoring (user does the work); keep wording aligned here only.
 */

export const STUDY_COACH_DEFAULT_PROMPT =
  "I need structured help with something I am learning. Please break it down step-by-step and explain the concepts so I understand and can finish the work myself:\n\n";

const PROMPTS = Object.freeze({
  math:
    "I have a math problem I need help with. Please walk me through it step-by-step, explaining the method and why each step works so I understand the concept, not just the answer:\n\n",
  science:
    "I have a science topic I am studying. Please explain the concept clearly with real-world examples, then help me reason through the question myself:\n\n",
  english:
    "I need help with an English writing or analysis task. Please give feedback, suggest improvements, and explain your reasoning so I can learn:\n\n",
  history:
    "I have a history question I am working through. Please provide historical context, key facts, and help me structure a clear argument:\n\n",
  code:
    "I have a programming exercise I am working on. Please explain the concept first, then guide me step-by-step rather than pasting a full solution:\n\n",
});

export const STUDY_COACH_SUBJECT_LABEL = Object.freeze({
  math: "Math",
  science: "Science",
  english: "English",
  history: "History",
  code: "Coding",
});

const ALIAS = Object.freeze({ coding: "code" });

/**
 * @param {string} raw - first token after /learn or /homework (any casing)
 * @returns {keyof typeof PROMPTS | ""}
 */
export function resolveStudyCoachSubjectKey(raw) {
  const k = String(raw || "").toLowerCase().trim();
  if (!k) return "";
  const mapped = ALIAS[k] || k;
  if (PROMPTS[mapped]) return mapped;
  return "";
}

/**
 * @param {string} rawSubjectArg - first subject token from slash input
 */
export function getStudyCoachPromptForSlashArg(rawSubjectArg) {
  const key = resolveStudyCoachSubjectKey(rawSubjectArg);
  if (!key) return STUDY_COACH_DEFAULT_PROMPT;
  return PROMPTS[key];
}

/**
 * Friendly label for kernel copy; unknown subjects echo the user token.
 * @param {string} rawSubjectArg - first token as typed (casing preserved for display fallback)
 */
export function getStudyCoachSlashDisplayLabel(rawSubjectArg) {
  const key = resolveStudyCoachSubjectKey(rawSubjectArg);
  if (key) return STUDY_COACH_SUBJECT_LABEL[key];
  const trimmed = String(rawSubjectArg || "").trim();
  return trimmed;
}

/** Rows for the study-coach subject card (order, chrome, and prompts). */
export const STUDY_COACH_SUBJECT_ROWS = Object.freeze([
  { id: "math", label: STUDY_COACH_SUBJECT_LABEL.math, emoji: "\u{1F4D0}", color: "#38bdf8", prompt: PROMPTS.math },
  { id: "science", label: STUDY_COACH_SUBJECT_LABEL.science, emoji: "\u{1F52C}", color: "#34d399", prompt: PROMPTS.science },
  { id: "english", label: STUDY_COACH_SUBJECT_LABEL.english, emoji: "\u{270D}\uFE0F", color: "#a78bfa", prompt: PROMPTS.english },
  { id: "history", label: STUDY_COACH_SUBJECT_LABEL.history, emoji: "\u{1F3DB}\uFE0F", color: "#fbbf24", prompt: PROMPTS.history },
  { id: "code", label: STUDY_COACH_SUBJECT_LABEL.code, emoji: "\u{1F4BB}", color: "#f472b6", prompt: PROMPTS.code },
  { id: "other", label: "Other", emoji: "\u{1F4DA}", color: "#94a3b8", prompt: STUDY_COACH_DEFAULT_PROMPT },
]);

