'use strict';

const fs = require('fs');
const path = require('path');

/**
 * Repo root for Electron `cwd` and asset paths in Playwright.
 * Prefer `NEURAL_E2E_REPO_ROOT` (seeded from `process.cwd()` in playwright.e2e.config.js)
 * so a junction/symlinked `e2e` __dirname does not launch a different physical clone than
 * the one where `npm run renderer:ensure-build` / `verify:ui` ran.
 */
function getE2ERepoRoot() {
    const fromEnv = process.env.NEURAL_E2E_REPO_ROOT && String(process.env.NEURAL_E2E_REPO_ROOT).trim();
    if (fromEnv) return path.resolve(fromEnv);
    const cwd = process.cwd();
    try {
        if (fs.existsSync(path.join(cwd, 'package.json')) && fs.existsSync(path.join(cwd, 'e2e'))) {
            return cwd;
        }
    } catch {
        // ignore
    }
    return path.resolve(__dirname, '..');
}

module.exports = { getE2ERepoRoot };

