'use strict';

/**
 * One-shot: point Electron launch cwd at NEURAL_E2E_REPO_ROOT (playwright config seeds from cwd).
 */
const fs = require('fs');
const path = require('path');

const repoRoot = path.resolve(__dirname, '..');
const e2eDir = path.join(repoRoot, 'e2e');

function walk(dir, out = []) {
    let names;
    try {
        names = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
        return out;
    }
    for (const ent of names) {
        const p = path.join(dir, ent.name);
        if (ent.isDirectory()) walk(p, out);
        else if (ent.isFile() && ent.name.endsWith('.js')) out.push(p);
    }
    return out;
}

function relRequire(fromFile) {
    const rel = path.relative(path.dirname(fromFile), path.join(e2eDir, 'repoRoot.cjs'));
    const norm = rel.split(path.sep).join('/');
    if (!norm.startsWith('.')) return `./${norm}`;
    return norm;
}

for (const file of walk(e2eDir)) {
    if (file.endsWith(`${path.sep}repoRoot.cjs`) || file.endsWith('repoRoot.cjs')) continue;

    let s = fs.readFileSync(file, 'utf8');
    const orig = s;
    const reqPath = relRequire(file);
    const reqLine = `const { getE2ERepoRoot } = require('${reqPath}');\n`;

    const needs =
        s.includes('path.resolve(__dirname, \'..\'') ||
        s.includes('path.resolve(__dirname, \"..\"') ||
        s.includes('path.resolve(__dirname, `..`');

    if (!needs) continue;

    if (!s.includes('getE2ERepoRoot') && !s.includes('repoRoot.cjs')) {
        const shebang = s.startsWith('#!') ? s.indexOf('\n') + 1 : 0;
        const insertAt = shebang;
        s = s.slice(0, insertAt) + reqLine + s.slice(insertAt);
    }

    s = s.split("cwd: path.resolve(__dirname, '..'),").join('cwd: getE2ERepoRoot(),');
    s = s.split('cwd: path.resolve(__dirname, ".."),').join('cwd: getE2ERepoRoot(),');
    s = s.split('path.resolve(__dirname, ".."),').join('getE2ERepoRoot(),');
    s = s.split("path.resolve(__dirname, '..'),").join('getE2ERepoRoot(),');

    s = s.split("path.resolve(__dirname, '..')").join('getE2ERepoRoot()');
    s = s.split('path.resolve(__dirname, "..")').join('getE2ERepoRoot()');

    if (s !== orig) {
        fs.writeFileSync(file, s, 'utf8');
        console.log('patched', path.relative(repoRoot, file));
