  const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), "neuralshell-e2e-agent-install-"));
  const app = await electron.launch({
    args: ["."],
    cwd: getE2ERepoRoot(),
    env: {
      ...process.env,
      NEURAL_USER_DATA_DIR: userDataDir,
      NEURAL_IGNORE_INTEGRITY: "1"
    }
  });

  try {
    const page = await app.firstWindow();
    await page.waitForLoadState("domcontentloaded");
    await expect(page.getByTestId("top-status-bar")).toBeVisible({ timeout: 20000 });
    const onboardingClose = page.getByTestId("onboarding-close-btn");
    if (await onboardingClose.count()) {
      await onboardingClose.first().click().catch(() => {});
      await page.waitForTimeout(150);
    }
    const skipWelcome = page.locator("button").filter({ hasText: /know my way around/i }).first();
    if (await skipWelcome.count()) {
      await skipWelcome.click().catch(() => {});
      await page.waitForTimeout(120);
    }
    await page.getByTestId("settings-open-btn").click();
    await expect(page.getByTestId("settings-drawer")).toBeVisible({ timeout: 15000 });
    await expect(page.getByTestId("agent-store")).toBeVisible();
    const installBtn = page.getByTestId("agent-store-install-proof_guard");
    await expect(installBtn).toBeVisible();
  } finally {
    await app.close();
    try {
      fs.rmSync(userDataDir, { recursive: true, force: true });
    } catch {
      // best effort
    }
  }
});

