export function isSetupComplete() {
    try {
        return localStorage.getItem(SETUP_COMPLETE_KEY) === '1';
    } catch {
        return false;
    }
}

export function markSetupComplete() {
    try {
        localStorage.setItem(SETUP_COMPLETE_KEY, '1');
    } catch { /* noop */ }
}

