const SetupScreen = React.memo(function SetupScreen({ onComplete, onSelectProvider }) {
    const [step, setStep] = useState(0);
    const [selectedProvider, setSelectedProvider] = useState('ollama');

    const handleFinish = useCallback(() => {
        markSetupComplete();
        if (typeof onSelectProvider === 'function') {
            onSelectProvider(selectedProvider);
        }
        if (typeof onComplete === 'function') {
            onComplete();
        }
    }, [onComplete, onSelectProvider, selectedProvider]);

    if (step === 0) {
        return (
            <div
                className="fixed inset-0 z-[200] overflow-hidden bg-[#030712]"
                role="dialog"
                aria-modal="true"
                aria-labelledby="setup-welcome-title"
