                            <div className="mb-8 text-center">
                                <div className="mb-5 inline-flex items-center gap-2 rounded-full border border-violet-400/25 bg-violet-500/10 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.2em] text-violet-200/90">
                                    <Sparkles className="h-3.5 w-3.5 text-violet-300" aria-hidden="true" />
