                                            type="button"
                                            onClick={() => setSelectedProvider(p.id)}
                                            className={`flex w-full items-start gap-3 rounded-xl border p-4 text-left transition-all duration-200 ${
                                                active
                                                    ? 'border-violet-400/45 bg-gradient-to-br from-violet-500/15 to-indigo-600/10 ring-1 ring-violet-400/25 shadow-[0_0_24px_-8px_rgba(139,92,246,0.35)]'
                                                    : 'border-white/[0.06] bg-white/[0.02] hover:border-white/12 hover:bg-white/[0.04]'
                                            }`}
                                        >
                                            <span className="text-xl leading-none" aria-hidden="true">{p.icon}</span>
                                            <div className="min-w-0 flex-1">
                                                <div className={`text-[14px] font-semibold ${active ? 'text-violet-100' : 'text-slate-200'}`}>
                                                    {p.name}
                                                </div>
                                                <div className="mt-0.5 text-[13px] text-slate-400">{p.desc}</div>
                                            </div>
                                            <div
                                                className={`mt-1 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 transition-colors ${
                                                    active
                                                        ? 'border-violet-400 bg-violet-500 text-white'
                                                        : 'border-slate-600 bg-transparent'
                                                }`}
                                                aria-hidden="true"
                                            >
                                                {active ? <span className="text-[10px] leading-none">✓</span> : null}
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>

                            <div className="flex items-center justify-between gap-4 border-t border-white/[0.06] pt-6">
                                <button
                                    type="button"
                                    onClick={() => setStep(0)}
                                    className="inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-[13px] font-medium text-slate-500 transition-colors hover:bg-white/[0.04] hover:text-slate-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-500/50"
                                >
                                    <ChevronLeft className="h-4 w-4" aria-hidden="true" />
                                    Back
                                </button>
                                <button
                                    type="button"
                                    data-testid="setup-launch-btn"
                                    onClick={handleFinish}
                                    className="group inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 px-7 py-3 text-[14px] font-semibold text-white shadow-lg shadow-violet-600/25 ring-1 ring-white/10 transition-all hover:from-violet-500 hover:to-indigo-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-violet-400/70 active:scale-[0.98]"
                                >
                                    Launch NeuralShell
                                    <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-0.5" aria-hidden="true" />
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return null;
});

export default SetupScreen;

