const applyLocalLanePreset = useCallback(async () => {
    if (!settings) return;
    setBusy(true);
    setConnectionReport(null);
    const next = {
        ...settings,
        provider: 'ollama',
        ollamaBaseUrl: defaultBaseUrlForProvider('ollama'),
        apiKey: '',
        apiKeyPresent: false,
        allowRemoteBridge: false,
        connectOnStartup: true,
    };
    const saved = await saveSettings(next, 'Ollama on this device: local endpoint saved. No API key. Auto-connect on startup.');
    if (saved) {
        const localModel = (PROVIDER_MODEL_SUGGESTIONS.ollama && PROVIDER_MODEL_SUGGESTIONS.ollama[0]) || 'llama3';
        setModelDraft(localModel);
        try {
            await window.api.state.update({ model: localModel });
        } catch {
            /* model bridge may be offline; draft still updated */
        }
        await runProviderSweep();
    }
    setBusy(false);
}, [runProviderSweep, saveSettings, settings]);

/** One-tap hosted lane: provider + default base URL + suggested model (API key unchanged). */
const applyHostedProviderShortcut = useCallback(async (targetProvider) => {
    if (!settings) return;
    const pid = String(targetProvider || '').trim().toLowerCase();
    if (!providerIsRemote(pid)) return;
    setBusy(true);
    setConnectionReport(null);
    const suggested = (PROVIDER_MODEL_SUGGESTIONS[pid] && PROVIDER_MODEL_SUGGESTIONS[pid][0])
        || (pid === 'openai' ? 'gpt-4o-mini' : 'llama3');
    const next = {
        ...settings,
        provider: pid,
        ollamaBaseUrl: defaultBaseUrlForProvider(pid),
        allowRemoteBridge: true,
        connectOnStartup: true,
        apiKeyPresent: providerRequiresApiKey(pid) ? Boolean(settings.apiKeyPresent) : false,
        apiKey: providerRequiresApiKey(pid) ? String(settings.apiKey || '') : '',
    };
    const label = PROVIDER_OPTIONS.find((o) => o.id === pid)?.label || pid;
    const saved = await saveSettings(
        next,
        `${label}: hosted endpoint saved. Add or confirm your API key, then Check Connection.`,
    );
    if (saved) {
        setModelDraft(suggested);
        try {
            await window.api.state.update({ model: suggested });
        } catch {
            /* optional */
        }
        await runProviderSweep();
    }
    setBusy(false);
}, [runProviderSweep, saveSettings, settings]);

const applyHostedLanePreset = useCallback(() => applyHostedProviderShortcut('openai'), [applyHostedProviderShortcut]);

