import { useState, useEffect, useCallback } from 'react';

const STORAGE_KEY = 'neuralshell_adaptive_layout_v1';

function readPanelsFromStorage() {
    if (typeof window === 'undefined' || !window.localStorage) return {};
    try {
        const raw = window.localStorage.getItem(STORAGE_KEY);
        const data = raw ? JSON.parse(raw) : null;
        return data && typeof data === 'object' && data.panels && typeof data.panels === 'object'
            ? data.panels
            : {};
    } catch {
        return {};
    }
}

/**
 * Reads Adaptive Layout Engine panel flags from localStorage and refreshes when
 * layout is applied or saved (custom layout name, etc.).
 */
export function useAdaptiveLayoutChrome() {
    const [panels, setPanels] = useState(() => readPanelsFromStorage());

    useEffect(() => {
        const refresh = () => setPanels(readPanelsFromStorage());
        window.addEventListener('neuralshell:apply-layout', refresh);
        window.addEventListener('neuralshell:layout-chrome-updated', refresh);
        window.addEventListener('storage', refresh);
        return () => {
            window.removeEventListener('neuralshell:apply-layout', refresh);
            window.removeEventListener('neuralshell:layout-chrome-updated', refresh);
            window.removeEventListener('storage', refresh);
        };
    }, []);

    const isPanelChromeVisible = useCallback((panelId, defaultVisible = true) => {
        if (!panelId) return defaultVisible;
        if (!Object.prototype.hasOwnProperty.call(panels, panelId)) return defaultVisible;
        return panels[panelId] !== false;
    }, [panels]);

    return { panels, isPanelChromeVisible };
}

