'use strict';

/**
 * Harden Electron E2E boot: first-run Setup can still appear if initScript ordering
 * or storage partitioning flakes. This module retries wizard clicks + localStorage seed + reload.
 */

const ONBOARDING_PROGRESS_DEFAULT = JSON.stringify({
    provider_sweep: true,
    vault_save: true,
    run_proof: true,
    share_badge: true,
});

async function installE2EProfileInitScript(page, progressJsonString) {
    const pj = progressJsonString || ONBOARDING_PROGRESS_DEFAULT;
    await page.addInitScript((progressJson) => {
        try {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
            globalThis.localStorage.setItem('neuralshell_setup_complete_v1', '1');
            globalThis.localStorage.setItem('neuralshell_first_boot_completed_v1', '1');
            globalThis.localStorage.setItem('neuralshell_first_boot_dismissed_v1', '1');
            globalThis.localStorage.setItem('neuralshell_welcome_overlay_dismissed_v1', '1');
            globalThis.localStorage.setItem('neuralshell_onboarding_progress_v1', progressJson);
        } catch {
            /* ignore */
        }
    }, pj);
}

/**
 * @param {import('@playwright/test').Page} page
 * @param {import('@playwright/test').expect} expect
 */
async function reloadAndAssertMainShell(page, expect, { timeoutMs = 90000 } = {}) {
    await page.reload({ waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(350);
    const bar = page.locator('[data-testid="top-status-bar"]');
    const perTry = Math.min(22000, Math.max(12000, Math.floor(timeoutMs / 4)));

    for (let attempt = 0; attempt < 5; attempt += 1) {
        try {
            await expect(bar).toBeVisible({ timeout: perTry });
            return;
        } catch {
            /* fall through to recovery */
        }

        const getStarted = page.getByTestId('setup-get-started-btn');
        if (await getStarted.count() && await getStarted.first().isVisible().catch(() => false)) {
            await getStarted.first().click();
            await page.waitForTimeout(450);
            continue;
        }

        const localPick = page.getByRole('button', { name: /Local \(Ollama\)/i }).first();
        if (await localPick.count() && await localPick.isVisible().catch(() => false)) {
            await localPick.click().catch(() => {});
            await page.waitForTimeout(220);
        }

        const launch = page.getByTestId('setup-launch-btn');
        if (await launch.count() && await launch.first().isVisible().catch(() => false)) {
            await launch.first().click();
            await page.waitForTimeout(900);
            continue;
        }

        await page.evaluate(() => {
            try {
                localStorage.setItem('neuralshell_setup_complete_v1', '1');
                localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
                localStorage.setItem('neuralshell_first_boot_completed_v1', '1');
                localStorage.setItem('neuralshell_first_boot_dismissed_v1', '1');
                localStorage.setItem('neuralshell_welcome_overlay_dismissed_v1', '1');
            } catch {
                /* ignore */
            }
        });
        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.waitForTimeout(400);
    }

    await expect(bar).toBeVisible({ timeout: 20000 });
}

module.exports = {
    ONBOARDING_PROGRESS_DEFAULT,
    installE2EProfileInitScript,
    reloadAndAssertMainShell,
};

