#!/usr/bin/env node
/**
 * Validates relative targets in docs/**/*.md (inline + reference-style links).
 * Skips http(s), mailto, tel, data URLs, and pure #-anchors.
 */
const fs = require("fs");
const path = require("path");

const repoRoot = path.resolve(__dirname, "..");
const docsRoot = path.join(repoRoot, "docs");

function walkMd(dir, acc = []) {
  if (!fs.existsSync(dir)) return acc;
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walkMd(p, acc);
    else if (ent.name.endsWith(".md")) acc.push(p);
  }
  return acc;
}

function stripFragment(href) {
  const i = href.indexOf("#");
  return i === -1 ? href : href.slice(0, i);
}

function shouldSkip(href) {
  const h = href.trim();
  if (!h || h.startsWith("#")) return true;
  if (/^(https?:|mailto:|tel:|data:)/i.test(h)) return true;
  return false;
}

function collectIssues(mdPath, text) {
  const baseDir = path.dirname(mdPath);
  const issues = [];

  const inline = /\]\(([^)\s]+)\)/g;
  let m;
  while ((m = inline.exec(text)) !== null) {
    let href = m[1].replace(/^<|>$/g, "");
    if (shouldSkip(href)) continue;
    const target = stripFragment(decodeURIComponent(href));
    if (!target) continue;
    const resolved = path.resolve(baseDir, target);
    if (!resolved.startsWith(docsRoot) && !resolved.startsWith(repoRoot)) {
      issues.push({ line: text.slice(0, m.index).split("\n").length, href, reason: "resolves outside repo" });
      continue;
    }
    if (!fs.existsSync(resolved)) {
      issues.push({ line: text.slice(0, m.index).split("\n").length, href, reason: "missing file" });
    }
  }

  const refStyle = /^[ \t]*\[[^\]]*]:\s*(\S+)/gm;
  while ((m = refStyle.exec(text)) !== null) {
    let href = m[1].replace(/[<>]/g, "");
    if (shouldSkip(href)) continue;
    const target = stripFragment(decodeURIComponent(href));
    if (!target) continue;
    const resolved = path.resolve(baseDir, target);
    if (!fs.existsSync(resolved)) {
      issues.push({ line: text.slice(0, m.index).split("\n").length, href, reason: "missing file (ref-style)" });
    }
  }

  return issues;
}

function main() {
  const files = walkMd(docsRoot);
  let total = 0;
  for (const file of files) {
    const rel = path.relative(repoRoot, file);
    const text = fs.readFileSync(file, "utf8");
    const issues = collectIssues(file, text);
    if (issues.length) {
      total += issues.length;
      console.error(`\n${rel}:`);
      for (const i of issues) {
        console.error(`  L${i.line}: ${i.reason}: ${i.href}`);
      }
    }
  }
  if (total) {
    console.error(`\ndocs-link-check: ${total} broken relative link(s)`);
    process.exit(1);
  }
  console.log(`docs-link-check: OK (${files.length} markdown files)`);
}

main();

