const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");

function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

function assertScriptOrder(scriptBody, before, after, label) {
  const iBefore = scriptBody.indexOf(before);
  const iAfter = scriptBody.indexOf(after);
  assert(iBefore !== -1, `${label} must include ${before}.`);
  assert(iAfter !== -1, `${label} must include ${after}.`);
  assert(iBefore < iAfter, `${label} must run ${before} before ${after}.`);
}

function run() {
  const packageJson = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
  const scripts = packageJson.scripts || {};
  const needle = "npm run docs:link-check";

  for (const name of ["verify:ship", "verify:all", "grade:a"]) {
    assert(String(scripts[name] || "").includes(needle), `${name} must include ${needle}.`);
  }

  assertScriptOrder(String(scripts.verify_ship || ""), "npm run lint", needle, "verify:ship");
  assertScriptOrder(String(scripts.verify_all || ""), "npm run lint", needle, "verify:all");
  assertScriptOrder(String(scripts.grade_a || ""), "npm run lint", needle, "grade:a");

  const prepush = fs.readFileSync(path.join(root, "scripts", "prepush-gate.js"), "utf8");
  assert(prepush.includes("docs:link-check"), "prepush-gate must invoke docs:link-check.");
  assert(
    prepush.includes("NEURAL_SKIP_DOCS_LINK_CHECK"),
    "prepush-gate must document NEURAL_SKIP_DOCS_LINK_CHECK."
  );

  console.log("Docs link check contract test passed.");
}

run();

