#!/usr/bin/env node
/**
 * Validates relative targets in docs markdown, selected repo subtrees, and repo-root *.md:
 * - Inline links, images, and reference-style targets
 * - Same-file #fragments and path#fragments for .md targets (GFM-style heading slugs + {#ids})
 * Skips http(s), mailto, tel, data URLs. Ignores bodies inside fenced ``` code blocks.
 */
const fs = require("fs");
const path = require("path");

const repoRoot = path.resolve(__dirname, "..");
const docsRoot = path.join(repoRoot, "docs");

/** Extra directories under repo root to scan recursively for *.md (paths are repo-relative). */
const EXTRA_MARKDOWN_DIRS = ["installer", "plugins", "beta"];

/** Set DOCS_LINK_CHECK_NO_ANCHORS=1 to skip fragment validation (path existence only). */
const ANCHORS_ENABLED = process.env.DOCS_LINK_CHECK_NO_ANCHORS !== "1";

function walkMd(dir, acc = []) {
  if (!fs.existsSync(dir)) return acc;
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walkMd(p, acc);
    else if (ent.name.endsWith(".md")) acc.push(p);
  }
  return acc;
}

function listRootMarkdownFiles() {
  return fs
    .readdirSync(repoRoot, { withFileTypes: true })
    .filter((e) => e.isFile() && e.name.endsWith(".md"))
    .map((e) => path.join(repoRoot, e.name));
}

function stripFragment(href) {
  const i = href.indexOf("#");
  return i === -1 ? href : href.slice(0, i);
}

/** Ranges [start, end) in text where link targets should be ignored (fenced code blocks). */
function fencedCodeRanges(text) {
  const lines = text.split("\n");
  const ranges = [];
  let inFence = false;
  let rangeStart = 0;
  let offset = 0;
  for (let li = 0; li < lines.length; li++) {
    const line = lines[li];
    const lineStart = offset;
    offset += line.length + 1;
    if (line.trimStart().startsWith("```")) {
      if (!inFence) {
        inFence = true;
        rangeStart = lineStart;
      } else {
        ranges.push([rangeStart, offset]);
        inFence = false;
      }
    }
  }
  return ranges;
}

function indexInFencedCode(idx, ranges) {
  return ranges.some(([a, b]) => idx >= a && idx < b);
}

function shouldSkipExternal(href) {
  const h = href.trim();
  if (!h) return true;
  if (/^(https?:|mailto:|tel:|data:)/i.test(h)) return true;
  return false;
}

/**
 * Parse markdown link/image target. Returns null to skip.
 * sameFileOnly: href is only #fragment (current md).
 */
function parseHref(raw) {
  const href = String(raw).trim().replace(/^<|>$/g, "");
  if (!href || shouldSkipExternal(href)) return null;
  if (href.startsWith("#")) {
    const frag = decodeURIComponent(href.slice(1));
    return { filePath: null, fragment: frag || null, sameFileOnly: true };
  }
  const hash = href.indexOf("#");
  const pathPart = hash === -1 ? href : href.slice(0, hash);
  const fragment = hash === -1 ? null : decodeURIComponent(href.slice(hash + 1));
  return {
    filePath: pathPart || null,
    fragment: fragment || null,
    sameFileOnly: false
  };
}

function lineAtIndex(text, idx) {
  return text.slice(0, idx).split("\n").length;
}

/** GFM/GitHub-style slug from heading plain text (unicode-aware). */
function slugifyHeading(text) {
  const t = String(text)
    .trim()
    .toLowerCase()
    .replace(/<[^>]+>/g, "");
  const slug = t
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "");
  return slug;
}

/** Collect heading-based anchors + explicit {#id} + simple HTML id= on heading tags. */
function buildMarkdownAnchorSet(source) {
  const anchors = new Set();
  const lines = source.split(/\r?\n/);
  const slugUseCount = new Map();

  for (const line of lines) {
    let m = /^(#{1,6})\s+(.+?)(?:\s+\{#([a-zA-Z][a-zA-Z0-9_.-]*)\})\s*$/.exec(line);
    let headingText;
    let explicitId = null;
    if (m) {
      headingText = m[2].trim();
      explicitId = m[3];
    } else {
      m = /^(#{1,6})\s+(.+?)\s*$/.exec(line);
      if (!m) continue;
      headingText = m[2].replace(/\s+#+\s*$/, "").trim();
    }
    if (explicitId) {
      anchors.add(explicitId.toLowerCase());
    }
    const base = slugifyHeading(headingText);
    if (base) {
      const n = slugUseCount.get(base) || 0;
      slugUseCount.set(base, n + 1);
      const slug = n === 0 ? base : `${base}-${n}`;
      anchors.add(slug);
    }
  }

  const htmlId = /<h[1-6][^>]*\bid=["']([^"']+)["'][^>]*>/gi;
  let hm;
  while ((hm = htmlId.exec(source)) !== null) {
    anchors.add(String(hm[1]).toLowerCase());
  }

  return anchors;
}

function getAnchorSet(absPath, cache) {
  if (cache.has(absPath)) return cache.get(absPath);
  const body = fs.readFileSync(absPath, "utf8");
  const set = buildMarkdownAnchorSet(body);
  cache.set(absPath, set);
  return set;
}

function normalizeFragment(frag) {
  if (frag == null || frag === "") return null;
  let f = String(frag).trim();
  if (f.toLowerCase().startsWith("user-content-")) {
    f = f.slice("user-content-".length);
  }
  return f.toLowerCase();
}

function validateTarget(baseDir, mdPath, rawHref, matchIndex, text, issues, skipRanges, anchorCache) {
  if (indexInFencedCode(matchIndex, skipRanges)) return;
  const parsed = parseHref(rawHref);
  if (!parsed) return;
  const line = lineAtIndex(text, matchIndex);

  let resolved;
  if (parsed.sameFileOnly) {
    resolved = mdPath;
  } else if (!parsed.filePath) {
    return;
  } else {
    let targetPath = parsed.filePath;
    try {
      targetPath = decodeURIComponent(targetPath);
    } catch {
      issues.push({ line, href: rawHref, reason: "invalid percent-encoding in path" });
      return;
    }
    resolved = path.resolve(baseDir, targetPath);
  }

  const relToRepo = path.relative(repoRoot, resolved);
  if (relToRepo.startsWith("..") || path.isAbsolute(relToRepo)) {
    issues.push({ line, href: rawHref, reason: "escapes repo root" });
    return;
  }
  if (!fs.existsSync(resolved)) {
    issues.push({ line, href: rawHref, reason: "missing file" });
    return;
  }

  if (!ANCHORS_ENABLED || !parsed.fragment) return;
  const frag = normalizeFragment(parsed.fragment);
  if (!frag) return;

  if (!String(resolved).toLowerCase().endsWith(".md")) return;

  const anchors = getAnchorSet(resolved, anchorCache);
  if (!anchors.has(frag)) {
    issues.push({
      line,
      href: rawHref,
      reason: `missing anchor #${parsed.fragment} in ${path.relative(repoRoot, resolved)}`
    });
  }
}

function collectIssues(mdPath, text, anchorCache) {
  const baseDir = path.dirname(mdPath);
  const issues = [];
  const skipRanges = fencedCodeRanges(text);

  const linkOrImage = /!?\[[^\]]*]\(([^)\s]+)\)/g;
  let m;
  while ((m = linkOrImage.exec(text)) !== null) {
    validateTarget(baseDir, mdPath, m[1], m.index, text, issues, skipRanges, anchorCache);
  }

  const refStyle = /^[ \t]*\[[^\]]*]:\s*(\S+)/gm;
  while ((m = refStyle.exec(text)) !== null) {
    if (indexInFencedCode(m.index, skipRanges)) continue;
    let href = m[1].replace(/[<>]/g, "");
    if (shouldSkipExternal(href)) continue;
    validateTarget(baseDir, mdPath, href, m.index, text, issues, skipRanges, anchorCache);
  }

  return issues;
}

function main() {
  const docFiles = walkMd(docsRoot);
  const extraFiles = [];
  for (const rel of EXTRA_MARKDOWN_DIRS) {
    const dir = path.join(repoRoot, rel);
    if (fs.existsSync(dir)) walkMd(dir, extraFiles);
  }
  const rootMd = listRootMarkdownFiles();
  const seen = new Set();
  const files = [];
  for (const f of [...docFiles, ...extraFiles, ...rootMd]) {
    if (seen.has(f)) continue;
    seen.add(f);
    files.push(f);
  }
  const anchorCache = new Map();
  let total = 0;
  for (const file of files) {
    const rel = path.relative(repoRoot, file);
    const text = fs.readFileSync(file, "utf8");
    const issues = collectIssues(file, text, anchorCache);
    if (issues.length) {
      total += issues.length;
      console.error(`\n${rel}:`);
      for (const i of issues) {
        console.error(`  L${i.line}: ${i.reason}: ${i.href}`);
      }
    }
  }
  if (total) {
    console.error(`\ndocs-link-check: ${total} issue(s)`);
    process.exit(1);
  }
  const anchorNote = ANCHORS_ENABLED ? "anchors on" : "anchors off (DOCS_LINK_CHECK_NO_ANCHORS=1)";
  console.log(
    `docs-link-check: OK (${docFiles.length} docs/, ${extraFiles.length} installer|plugins|beta, ${rootMd.length} root *.md; ${anchorNote})`
  );
}

main();

// Exported for unit tests (slug + anchor builder).
if (require.main === module) {
  /* noop */
} else {
  module.exports = { slugifyHeading, buildMarkdownAnchorSet, parseHref };
}

