/** Single-line `` `...` `` spans (not ``` fences). */
function inlineCodeRanges(text) {
  const ranges = [];
  let i = 0;
  while (i < text.length) {
    if (text[i] === "`" && text[i + 1] === "`" && text[i + 2] === "`") {
      i += 3;
      continue;
    }
    if (text[i] === "`") {
      const start = i;
      i++;
      while (i < text.length && text[i] !== "`" && text[i] !== "\n") i += 1;
      if (i < text.length && text[i] === "`") {
        ranges.push([start, i + 1]);
        i += 1;
        continue;
      }
    }
    i += 1;
  }
  return ranges;
}

function indexInSkippedRegions(idx, fencedRanges, inlineRanges) {
  return indexInFencedCode(idx, fencedRanges) || indexInFencedCode(idx, inlineRanges);
