/** Replace fenced regions with spaces (same length) so inline backtick scan ignores ``` bodies. */
function blankFencedRegionsForInlineScan(text, fencedRanges) {
  if (!fencedRanges.length) return text;
  const sorted = [...fencedRanges].sort((a, b) => a[0] - b[0]);
  let out = "";
  let cur = 0;
  for (const [a, b] of sorted) {
    const start = Math.max(0, a);
    const end = Math.min(b, text.length);
    if (start > text.length) break;
    out += text.slice(cur, start);
    out += " ".repeat(Math.max(0, end - start));
    cur = Math.max(cur, end);
  }
  out += text.slice(cur);
  return out;
}

