/**
 * Parse markdown link/image target. Returns null to skip or on decode error.
 * When `issues` is provided, decode failures append a diagnostic row.
 * sameFileOnly: href is only #fragment (current md).
 */
function parseHref(raw, issues = null, line = 1) {
  const href = String(raw).trim().replace(/^<|>$/g, "");
  if (!href || shouldSkipExternal(href)) return null;

  const decodePart = (part, label) => {
    try {
      return decodeURIComponent(part);
    } catch {
      if (issues) issues.push({ line, href: raw, reason: `invalid URI encoding (${label})` });
      return null;
    }
  };

  if (href.startsWith("#")) {
    const frag = decodePart(href.slice(1), "fragment");
    if (frag === null && href.length > 1) return null;
    return { filePath: null, fragment: frag || null, sameFileOnly: true };
  }
  const hash = href.indexOf("#");
  const pathPart = hash === -1 ? href : href.slice(0, hash);
  let fragment = null;
  if (hash !== -1) {
    fragment = decodePart(href.slice(hash + 1), "fragment");
    if (fragment === null && href.slice(hash + 1).includes("%")) return null;
  }
  const decodedPath = decodePart(pathPart, "path");
  if (decodedPath === null) return null;
  return {
    filePath: decodedPath || null,
    fragment: fragment || null,
    sameFileOnly: false
  };
}

