#!/usr/bin/env node
/**
 * Parses docs or MILESTONE_ROADMAP_TODO.md for "## Milestone ..." sections and counts checkbox items.
 * Use: npm run roadmap:status [--json] [--strict] [--quiet]
 *   --strict  same as ROADMAP_STRICT=1 (fails if Milestone A has any open item)
 *   --quiet   one-line summary (or JSON only with --json)
 */
const fs = require("fs");
const path = require("path");

const repoRoot = path.resolve(__dirname, "..");
const defaultPath = path.join(repoRoot, "docs", "MILESTONE_ROADMAP_TODO.md");

function parseMilestones(text) {
  const milestones = [];
  const lines = text.split(/\n/");
  let current = null;
  for (const line of lines) {
    if (/^## Milestone\b/.test(line)) {
      current = { title: line.replace(/^##\s+/, "").trim(), done: 0, open: 0 };
      milestones.push(current);
      continue;
    }
    const c = /^- \[([ xX])\]\s+(.+)$/.exec(line);
    if (c && current) {
      const done = String(c[1]).toLowerCase() === "x";
      if (done) current.done += 1;
      else current.open += 1;
    }
  }
  return milestones;
}

function main() {
  const fileArg = process.argv.find((a) => a.startsWith("--file="));
  const roadmapPath = fileArg ? path.resolve(repoRoot, fileArg.slice("--file=".length)) : defaultPath;
  const wantJson = process.argv.includes("--json");
  const quiet = process.argv.includes("--quiet");

  if (!fs.existsSync(roadmapPath)) {
    console.error(`roadmap-status: missing ${path.relative(repoRoot, roadmapPath)}`);
    process.exit(1);
  }
  const text = fs.readFileSync(roadmapPath, "utf8");
  const milestones = parseMilestones(text);
  let totalDone = 0;
  let totalOpen = 0;
  for (const m of milestones) {
    totalDone += m.done;
    totalOpen += m.open;
  }

  if (wantJson) {
    console.log(JSON.stringify({ milestones, totalDone, totalOpen, path: path.relative(repoRoot, roadmapPath) }, null, 2));
  } else if (quiet) {
    console.log(
      `roadmap-status: ${path.relative(repoRoot, roadmapPath)} — ${totalOpen} open, ${totalDone} done (${milestones.length} milestones)`
    );
  } else {
    console.log("roadmap-status: " + path.relative(repoRoot, roadmapPath));
    for (const m of milestones) {
      console.log(`  ${m.title}: ${m.done} done, ${m.open} open`);
    }
    console.log(`  TOTAL: ${totalDone} done, ${totalOpen} open`);
  }

  const strict = process.env.ROADMAP_STRICT === "1" || process.argv.includes("--strict");
  if (strict && milestones.length) {
    const first = milestones[0];
    if (first.open > 0) {
      console.error(`roadmap-status: strict mode but "${first.title}" still has ${first.open} open item(s).`);
      process.exit(1);
    }
  }
}

main();

const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function run() {
  const wfDir = path.join(root, ".github", "workflows");
  assert(fs.existsSync(wfDir), ".github/workflows must exist");
  const files = fs.readdirSync(wfDir).filter((f) => f.endsWith(".yml") || f.endsWith(".yaml"));
  for (const name of files) {
    const full = path.join(wfDir, name);
    const text = fs.readFileSync(full, "utf8");
    if (text.includes("npm run docs:link-check") && !text.includes("npm run roadmap:status")) {
      throw new Error(`${name}: runs docs:link-check but missing npm run roadmap:status`);
    }
  }

  const out = execFileSync(process.execPath, [path.join(root, "scripts", "roadmap-status.cjs"), "--quiet"], {
    encoding: "utf8",
    cwd: root
  });
  assert(/open/i.test(out), "roadmap-status --quiet should mention open count");
  assert(/done/i.test(out), "roadmap-status --quiet should mention done count");

  console.log("CI doc gates parity test passed.");
}

run();

