#!/usr/bin/env node
/**
 * Deterministic "30-day ruin" tabletop / readiness narrative.
 * Prints one stressor per day (compressed calendar) for drills, board prep, or runbooks.
 *
 * Usage:
 *   node scripts/simulate-30-day-ruin.cjs
 *   node scripts/simulate-30-day-ruin.cjs --json
 *   node scripts/simulate-30-day-ruin.cjs --quiet
 */

const DAYS = [
  { stressor: "Silent TLS expiry on internal artifact mirror", blast: "build lane", mitigate: "pin dates + automated cert inventory" },
  { stressor: "Ollama daemon stops after OS patch; users blame 'the model'", blast: "support", mitigate: "offline quickstart + status copy" },
  { stressor: "Hosted model proxy rate cap hit during demo week", blast: "GTM", mitigate: "local-first path + cap telemetry" },
  { stressor: "Revoked intermediate appears in trust bundle cache", blast: "identity", mitigate: "trust path revalidation drill" },
  { stressor: "Stale air-gap update pack presented as 'latest'", blast: "updates", mitigate: "reject stale pack policy + quarantine" },
  { stressor: "Fleet heartbeat dropout on 18% of nodes", blast: "fleet", mitigate: "degraded mode + incident suggestion" },
  { stressor: "Break-glass credential used outside approved window", blast: "security", mitigate: "dual signoff + audit append" },
  { stressor: "Policy bundle drift between regions", blast: "policy", mitigate: "rollback gate + diff alert" },
  { stressor: "Session envelope checksum mismatch after bad restore", blast: "custody", mitigate: "quarantine + repair index" },
  { stressor: "Bridge auto-connect fights offline kill switch expectations", blast: "reliability", mitigate: "document connectOnStartup vs airgap" },
  { stressor: "Renderer crash loop from bad shell extension JSON", blast: "extensions", mitigate: "import validation + disable path" },
  { stressor: "Telemetry export enabled without consent in one tenant image", blast: "compliance", mitigate: "defaults off + consent audit" },
  { stressor: "Hardware binding mismatch after VM migration", blast: "licensing", mitigate: "rotation path + operator messaging" },
  { stressor: "Courier transfer package fails signature check mid-field", blast: "air gap", mitigate: "verify workflow + spare pack" },
  { stressor: "Incident queue floods from duplicate watchdog rules", blast: "incident", mitigate: "dedupe + severity caps" },
  { stressor: "Canvas snapshot import accepts schema-valid hostile payload", blast: "UX", mitigate: "validateSnapshot bounds" },
  { stressor: "Mission Control drills not run for 21 days; scorecard stale", blast: "readiness", mitigate: "schedule continuity drills" },
  { stressor: "Proof relay misconfigured; outbound blocked by firewall", blast: "proof", mitigate: "relay health + local fallback" },
  { stressor: "Operator home launcher hash opens wrong panel slug", blast: "routing", mitigate: "hash allowlist regression" },
  { stressor: "Multi-region backup restore completes but trust not re-sealed", blast: "DR", mitigate: "post-restore trust checklist" },
  { stressor: "Auto-update channel serves mismatched channel metadata", blast: "updates", mitigate: "channel verification + rollback" },
  { stressor: "API key exfil attempt via pasted chat (social)", blast: "human", mitigate: "paste warnings + secret scan" },
  { stressor: "Model pool idle unload evicts hot model mid-demo", blast: "perf", mitigate: "pool tuning + demo profile" },
  { stressor: "Workspace action guard false negative on traversal path", blast: "safety", mitigate: "path normalization tests" },
  { stressor: "Governance manifest drift vs shipped renderer", blast: "supply chain", mitigate: "governance:sync gate" },
  { stressor: "E2E flake masks real regression in calendar popover", blast: "QA", mitigate: "backdrop rules + escape sequencing" },
  { stressor: "Executive dashboard shows green while nodes degraded", blast: "observability", mitigate: "SLO wiring + drill evidence" },
  { stressor: "Vendor SLA breach; bridge latency spikes over 30s", blast: "vendor", mitigate: "timeout + user-facing degrade" },
  { stressor: "Regulator asks for 30-day evidence bundle in 48h", blast: "legal", mitigate: "export audit + continuity evidence" },
  { stressor: "Post-mortem: root cause chain spans 6 teams; no single owner", blast: "culture", mitigate: "single incident commander + timeline" }
];

function buildReport() {
  const days = DAYS.map((entry, i) => ({
    day: i + 1,
    stressor: entry.stressor,
    blastRadius: entry.blast,
    mitigation: entry.mitigate
  }));
  return {
    scenarioId: "thirty_day_ruin_tabletop",
    title: "30-Day Ruin Tabletop (compressed)",
    generatedAt: new Date().toISOString(),
    days,
    exitCriteria: [
      "One written timeline from day 1 → 30 with owners",
      "Evidence exports exist for trust, updates, and fleet branches",
      "Continuity Drill Center run recorded (pass or intentional fail with deltas)"
    ]
  };
}

function formatHuman(report) {
  const lines = [
    `${report.title}`,
    `Generated: ${report.generatedAt}`,
    "",
    ...report.days.map((d) => `Day ${String(d.day).padStart(2, "0")} [${d.blastRadius}] ${d.stressor} → ${d.mitigation}`),
    "",
    "Exit criteria:",
    ...report.exitCriteria.map((c) => `  - ${c}`)
  ];
  return lines.join("\n");
}

function main() {
  const argv = process.argv.slice(2);
  const wantJson = argv.includes("--json");
  const quiet = argv.includes("--quiet");

  const report = buildReport();

  if (wantJson) {
    process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
    return;
  }

  if (quiet) {
    process.stdout.write(
      `30-day-ruin: ${report.days.length} days, scenario=${report.scenarioId}, at=${report.generatedAt}\n`
    );
    return;
  }

  process.stdout.write(`${formatHuman(report)}\n`);
}

main();

